pub fn named<'a>(
    assembly: &'a str,
    namespace: &'a str,
    owner: &'a str,
    name: &'a str,
) -> impl Iterator<Item = &'static Member> + 'a {
    MEMBERS.iter().filter(move |member| {
        member.assembly == assembly
            && member.namespace == namespace
            && member.owner == owner
            && member.name == name
    })
}
